# Research-ORCID: https://orcid.org/0009-0001-1634-7063
# Attribution-Recorded-On: 2026-11-06
# Reuse: preserve upstream Apache-2.0 notices and cite the author of original changes.
# Make sure kaggle_challenge holds exactly ROWS rows generated by the official generator.
ROWS=$1
P="psql -U postgres -h /var/run/postgresql -qAtX"
have=$($P -d kaggle_challenge -c "SELECT count(*) FROM public.raw_data" 2>/dev/null || echo 0)
if [ "$have" != "$ROWS" ]; then
  echo "[gen] generating $ROWS rows (found: $have)"
  t0=$(date +%s)
  extra=""; $P -d postgres -c "SELECT 1 FROM pg_database WHERE datname='kaggle_challenge'" | grep -q 1 && extra="--replace"
  mkdir -p /results/r${ROWS}
  su pdm -c "cd /work/upstream && PG_KAGGLE_CHALLENGE_PASS='$PG_KAGGLE_CHALLENGE_PASS' python3 generate_database.py --rows $ROWS --host 127.0.0.1 --postgres_port 5432 --user pdm --admin_database postgres $extra" > /results/r${ROWS}/generate.log 2>&1 || { echo "[gen] FAILED"; tail -30 /results/r${ROWS}/generate.log; exit 2; }
  echo "[gen] $(( $(date +%s) - t0 )) s"
  # Lazily created Manager metadata (row counters, control schema) via one discarded legacy run.
  bash /work/bench/reset.sh >/dev/null 2>&1
  python3 /work/bench/harness.py --app-dir /work/solution --tag warmup --out /results/r${ROWS}/warmup --recipes "/work/upstream/SQL files" >/dev/null 2>&1
fi
